Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Section RgbcW.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O2Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

(* [comment removed for export] *)
Lemma rc_col : forall k regs M (s j w ps pd dlo dhi : Z),
  (64 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= j < w)%Z -> Z.of_nat k = (w - j)%Z -> (w < 2 ^ 31)%Z ->
  (0 <= ps)%Z -> (ps + 4 * w + 8 <= 2 ^ 64)%Z -> (0 <= pd)%Z -> (pd + w + 8 <= 2 ^ 64)%Z ->
  (0 <= dlo)%Z -> (dhi <= s - 64)%Z ->
  (forall q, (j <= q < w)%Z -> dlo <= xor3 (pd + q) /\ xor3 (pd + q) + 1 <= dhi)%Z ->
  (forall q, (j <= q < w)%Z -> ~ (dlo <= xor3 (ps + 4 * q) < dhi))%Z ->
  (forall q, (j <= q < w)%Z -> exists b : byte, M (Z_to_bv 64 (xor3 (ps + 4 * q))) = Some b) ->
  store_ok SEGS M (Z_to_bv 64 dlo) (Z.to_nat (dhi - dlo)) = true ->
  rdn SEGS M (Z_to_bv 64 (s - 60)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 w)) ->
  getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 13 = Z_to_bv 64 j -> getr regs 15 = Z_to_bv 64 (ps + 4 * j) -> getr regs 16 = Z_to_bv 64 (pd + j) ->
  exists regs' M',
    msteps SEGS (mkst regs (0x1ad60 : word) M al_rom) (mkst regs' (0x1ad3c : word) M' al_rom)
    /\ winside dlo dhi M M' /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 14 = Z_to_bv 64 w
