(* [comment removed for export] *)
Lemma rc_rows : forall k regs M (s i h w comp datas wpls datad wpld : Z),
  (64 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= i < h)%Z -> Z.of_nat k = (h - i)%Z -> (h < 2 ^ 31)%Z -> (1 <= w < 2 ^ 31)%Z -> (0 <= comp <= 2)%Z ->
  (datas mod 4 = 0)%Z -> (0 <= datas)%Z -> (w <= wpls)%Z -> (datas + 4 * (wpls * h) + 16 <= 2 ^ 64)%Z ->
  (datad mod 4 = 0)%Z -> (0 <= datad)%Z -> (0 <= wpld)%Z -> (w <= 4 * wpld)%Z -> (datad + 4 * (wpld * h) + 16 <= s - 64)%Z ->
  (datas + 4 * (wpls * h) <= datad \/ datad + 4 * (wpld * h) <= datas)%Z ->
  (forall a, (datas <= a < datas + 4 * (wpls * h))%Z -> exists b : byte, M (Z_to_bv 64 a) = Some b) ->
  store_ok SEGS M (Z_to_bv 64 datad) (Z.to_nat (4 * (wpld * h))) = true ->
  rdn SEGS M (Z_to_bv 64 (s - 60)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 w)) ->
  rdn SEGS M (Z_to_bv 64 (s - 64)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 h)) ->
  getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 11 = Z_to_bv 64 i -> getr regs 14 = Z_to_bv 64 w ->
  getr regs 9 = Z_to_bv 64 (datas + comp + 4 * wpls * i) -> getr regs 10 = Z_to_bv 64 (datad + 4 * wpld * i) ->
  getr regs 18 = Z_to_bv 64 (4 * wpls) -> getr regs 19 = Z_to_bv 64 (4 * wpld) ->
  exists regs' M',
    msteps SEGS (mkst regs (0x1ad50 : word) M al_rom) (mkst regs' (0x1ad88 : word) M' al_rom)
    /\ winside datad (datad + 4 * (wpld * h)) M M' /\ getr regs' 2 = Z_to_bv 64 (s - 64)
